use desigma_doc::*;
use desigma_engine::{edit::Edit, layout::layout_node};
use desigma_svg::import_svg_named;
use serde_json::Value;
use std::{collections::BTreeMap, fs, path::{Path, PathBuf}};

fn c(h:&str)->Color{Color::from_hex(h).unwrap()}
fn put(d:&mut Document,p:NodeId,mut n:Node,name:&str)->NodeId{n.name=name.into();d.insert(p,n).unwrap()}
fn frame(d:&mut Document,p:NodeId,name:&str,w:f32,h:f32,dir:LayoutDirection,gap:f32,pad:[f32;4])->NodeId{
 let id=d.alloc_id();let mut n=Node::frame(id,Rect::new(0.,0.,w,h));n.fills.clear();let fp=n.kind.frame_props_mut().unwrap();fp.clips_content=true;
 fp.auto_layout=Some(AutoLayout{direction:dir,wrap:false,item_spacing:gap,counter_spacing:gap,padding:pad,primary_align:LayoutAlign::Start,counter_align:LayoutAlign::Center,primary_sizing:Sizing::Fixed,counter_sizing:Sizing::Fixed,stroke_included:true,reverse_z:false});put(d,p,n,name)
}
fn fill(d:&mut Document,id:NodeId,h:&str,a:f32){d.get_mut(id).unwrap().fills=vec![Paint::solid(c(h).with_alpha(a))]}
fn outline(d:&mut Document,id:NodeId,h:&str,a:f32,w:f32){let n=d.get_mut(id).unwrap();n.stroke.paints=vec![Paint::solid(c(h).with_alpha(a))];n.stroke.weight=w}
fn round(d:&mut Document,id:NodeId,r:f32){d.get_mut(id).unwrap().corner_radii=[r;4]}
fn text(d:&mut Document,p:NodeId,name:&str,s:&str,w:f32,h:f32,size:f32,weight:u16,color:Color,align:TextAlignH)->NodeId{
 let id=d.alloc_id();let st=TextStyle{font_family:"Roboto".into(),font_weight:weight,font_size:size,line_height:LineHeight::Pixels(size*1.18),align_h:align,align_v:TextAlignV::Center,fills:vec![Paint::solid(color)],..Default::default()};
 let mut n=Node::text(id,Rect::new(0.,0.,w,h),s,st);if let NodeKind::Text(t)=&mut n.kind{t.auto_resize=TextAutoResize::Height}put(d,p,n,name)
}
fn bind(d:&mut Document,id:NodeId,var:&str){d.get_mut(id).unwrap().variables.bindings.insert("characters".into(),var.into());}
fn comp(d:&mut Document,p:NodeId,name:&str,w:f32,h:f32,dir:LayoutDirection,gap:f32,pad:[f32;4])->NodeId{
 let id=d.alloc_id();let n=Node::new(id,NodeKind::Component(FrameProps{clips_content:true,auto_layout:Some(AutoLayout{direction:dir,wrap:false,item_spacing:gap,counter_spacing:gap,padding:pad,primary_align:LayoutAlign::Center,counter_align:LayoutAlign::Center,primary_sizing:Sizing::Fixed,counter_sizing:Sizing::Fixed,stroke_included:true,reverse_z:false}),grids:vec![]}));
 let id=put(d,p,n,name);d.get_mut(id).unwrap().size=Vec2::new(w,h);id
}
fn inst(d:&mut Document,p:NodeId,name:&str,src:NodeId,w:f32,h:f32)->NodeId{let id=d.alloc_id();let mut n=Node::new(id,NodeKind::Instance{frame:FrameProps::default(),component:Some(src),component_key:None});n.size=Vec2::new(w,h);put(d,p,n,name)}
fn locale<'a>(j:&'a Value,code:&str)->&'a Value{j.as_array().unwrap().iter().find(|x|x["country_code"]==code).unwrap()}
fn variables(d:&mut Document,root:&Path)->BTreeMap<String,String>{
 let j:Value=serde_json::from_slice(&fs::read(root.join("assets/locale/translate/locale.json")).unwrap()).unwrap();
 let keys=["Who Am I?","Chameleon","Chameleon setup","Chameleons","Players","Start game","Your turn","Hold to reveal your word","Next player","The secret word was:","The Chameleon was:","Play again","Main menu","Animals","Music","Movies","Tv Show","Food","History","Sport","World","Electronics","Science","Celebrities","Video Games","Brands","Superhero","90s","Cartoon","Halloween","Christmas","Valentine","Easter"];
 let ids:Vec<String>=(0..keys.len()).map(|i|format!("copy-{i:02}")).collect();d.variable_collections.insert("language".into(),VariableCollection{id:"language".into(),name:"Language".into(),modes:vec![VariableMode{id:"en".into(),name:"English".into()},VariableMode{id:"da".into(),name:"Dansk".into()},VariableMode{id:"no".into(),name:"Norsk".into()},VariableMode{id:"sv".into(),name:"Svenska".into()}],default_mode:"en".into(),variables:ids.clone(),key:None});
 let mut out=BTreeMap::new();for (key,id) in keys.iter().zip(ids){let vals=[("en_US","en"),("da_DK","da"),("nb_NO","no"),("sv_SE","sv")].into_iter().map(|(l,m)|(m.into(),VariableValue::String(locale(&j,l)["texts"][key].as_str().unwrap_or(key).into()))).collect();d.variables.insert(id.clone(),Variable{id:id.clone(),name:format!("Copy/{key}"),collection:"language".into(),kind:VariableKind::String,values:vals,description:"Source: assets/locale/translate/locale.json".into(),scopes:vec!["TEXT_CONTENT".into()],hidden_from_publishing:false,key:None});out.insert((*key).into(),id);}for (i,(key,en,da,no,sv)) in [("BIG LAUGHS. TINY CLUES.","BIG LAUGHS. TINY CLUES.","STORE GRIN. SMÅ LEDETRÅDE.","STORE LATTERE. SMÅ HINT.","STORA SKRATT. SMÅ LEDTRÅDAR."),("A fast party game for every group","A fast party game for every group","Et hurtigt selskabsspil til enhver gruppe","Et raskt selskapsspill for alle grupper","Ett snabbt sällskapsspel för alla grupper"),("ONE APP. ENDLESS LAUGHS.","ONE APP. ENDLESS LAUGHS.","ÉN APP. UENDELIGE GRIN.","ÉN APP. ENDELØS LATTER.","EN APP. OÄNDLIGA SKRATT."),("CHRISTMAS GAME NIGHT","CHRISTMAS GAME NIGHT","JULESPILSAFTEN","JULESPILLKVELD","JULSPELSKVÄLL"),("CHRISTMAS EDITION","CHRISTMAS EDITION","JULEUDGAVE","JULEUTGAVE","JULUTGÅVA")].into_iter().enumerate(){let id=format!("store-copy-{i}");let vals=[("en",en),("da",da),("no",no),("sv",sv)].into_iter().map(|(m,s)|(m.into(),VariableValue::String(s.into()))).collect();d.variable_collections.get_mut("language").unwrap().variables.push(id.clone());d.variables.insert(id.clone(),Variable{id:id.clone(),name:format!("Store Copy/{key}"),collection:"language".into(),kind:VariableKind::String,values:vals,description:"Store promotion copy".into(),scopes:vec!["TEXT_CONTENT".into()],hidden_from_publishing:false,key:None});out.insert(key.into(),id);}out
}
fn background(d:&mut Document,p:NodeId,root:&Path,w:f32,h:f32){let key="app-bg";if !d.images.contains_key(key){d.images.insert(key.into(),fs::read(root.join("assets/bg.jpg")).unwrap());}let id=d.alloc_id();let mut n=Node::rectangle(id,Rect::new(0.,0.,w,h));n.fills=vec![Paint{kind:PaintKind::Image{image_ref:key.into(),scale_mode:ImageScaleMode::Fill},opacity:1.,visible:true,blend:BlendMode::Normal}];n.layout_child.absolute=true;n.constraints.horizontal=Constraint::Stretch;n.constraints.vertical=Constraint::Stretch;put(d,p,n,"ASSET/Background • source image") ;}
fn mode(d:&mut Document,id:NodeId,m:&str){d.get_mut(id).unwrap().variables.modes.insert("language".into(),m.into());}
fn screen(d:&mut Document,p:NodeId,root:&Path,name:&str,w:f32,h:f32)->NodeId{let id=frame(d,p,name,w,h,LayoutDirection::Vertical,0.,[0.;4]);let fp=d.get(id).unwrap().kind.frame_props().unwrap().clone();d.get_mut(id).unwrap().kind=NodeKind::Component(fp);fill(d,id,"0E2A50",1.);background(d,id,root,w,h);d.get_mut(id).unwrap().export_settings.push(ExportPreset{format:ExportFileFormat::Png,constraint:ExportConstraint::Scale(1.),suffix:String::new()});id}
fn card(d:&mut Document,p:NodeId,name:&str,w:f32,h:f32)->NodeId{let id=frame(d,p,name,w,h,LayoutDirection::Vertical,8.,[16.;4]);fill(d,id,"FFFFFF",0.16);outline(d,id,"FFFFFF",0.3,1.);round(d,id,22.);id}

struct Kit{button:NodeId,tile:NodeId,close:NodeId,icons:BTreeMap<String,NodeId>}
fn white_subtree(d:&mut Document,id:NodeId){let children=d.get(id).unwrap().children.clone();let leaf=matches!(d.get(id).unwrap().kind,NodeKind::Vector{..}|NodeKind::Rectangle|NodeKind::Ellipse(_));if leaf&&!d.get(id).unwrap().fills.is_empty(){d.get_mut(id).unwrap().fills=vec![Paint::solid(Color::WHITE)]}else if !leaf{d.get_mut(id).unwrap().fills.clear()}for child in children{white_subtree(d,child)}}
fn icon_component(d:&mut Document,p:NodeId,root:&Path,name:&str,path:&str)->NodeId{let svg=fs::read_to_string(root.join(path)).unwrap();let id=import_svg_named(&svg,&format!("Icon/{name}"),d,p,Vec2::ZERO).unwrap();let fp=d.get(id).unwrap().kind.frame_props().unwrap().clone();d.get_mut(id).unwrap().kind=NodeKind::Component(fp);white_subtree(d,id);id}
fn glyph_icon_component(d:&mut Document,p:NodeId,name:&str,glyph:&str)->NodeId{let id=comp(d,p,&format!("Icon/{name}"),32.,32.,LayoutDirection::Horizontal,0.,[0.;4]);text(d,id,"Glyph",glyph,32.,32.,26.,500,Color::WHITE,TextAlignH::Center);id}
fn kit(d:&mut Document,root:&Path,v:&BTreeMap<String,String>)->Kit{
 let pg=d.add_page("01 • Components");let board=frame(d,pg,"COMPONENT LIBRARY",2200.,1500.,LayoutDirection::Vertical,46.,[80.;4]);fill(d,board,"F3F4F6",1.);
 let b=comp(d,board,"Button / Glass / Large",310.,72.,LayoutDirection::Horizontal,0.,[15.,28.,15.,28.]);fill(d,b,"FFFFFF",0.18);outline(d,b,"FFFFFF",0.45,1.5);round(d,b,36.);d.get_mut(b).unwrap().component.props.push(ComponentPropDef{name:"Label".into(),kind:PropKind::Text,default:PropValue::Text("Button".into())});let bt=text(d,b,"Label","Button",254.,42.,28.,700,Color::WHITE,TextAlignH::Center);d.get_mut(bt).unwrap().component.bindings.insert(OverrideField::Characters,"Label".into());
 let icon_row=frame(d,board,"ICON COMPONENTS • editable vectors",1900.,100.,LayoutDirection::Horizontal,36.,[18.;4]);let mut icons=BTreeMap::new();for (name,path) in [("Animals","assets/icons/animal.svg"),("Music","assets/icons/music.svg"),("Movies","assets/icons/movie.svg"),("Food","assets/icons/food.svg")]{icons.insert(name.into(),icon_component(d,icon_row,root,name,path));}icons.insert("Tv Show".into(),glyph_icon_component(d,icon_row,"Tv Show","▣"));icons.insert("History".into(),glyph_icon_component(d,icon_row,"History","▤"));
 let tile=comp(d,board,"Category Tile / Responsive",160.,186.,LayoutDirection::Vertical,14.,[22.,10.,18.,10.]);fill(d,tile,"35A3ED",0.5);outline(d,tile,"FFFFFF",0.3,1.);round(d,tile,22.);d.get_mut(tile).unwrap().component.props=vec![ComponentPropDef{name:"Label".into(),kind:PropKind::Text,default:PropValue::Text("Animals".into())},ComponentPropDef{name:"Icon".into(),kind:PropKind::InstanceSwap{preferred:icons.values().copied().collect()},default:PropValue::Instance(icons["Animals"])}];let ii=inst(d,tile,"Icon",icons["Animals"],60.,60.);d.get_mut(ii).unwrap().component.bindings.insert(OverrideField::MainComponent,"Icon".into());let tt=text(d,tile,"Label","Animals",140.,40.,23.,700,Color::WHITE,TextAlignH::Center);d.get_mut(tt).unwrap().component.bindings.insert(OverrideField::Characters,"Label".into());
 let close=comp(d,board,"Icon Button / Close",48.,48.,LayoutDirection::Horizontal,0.,[0.;4]);fill(d,close,"FFFFFF",0.18);outline(d,close,"FFFFFF",0.35,1.);round(d,close,24.);text(d,close,"Glyph","×",48.,48.,36.,400,Color::WHITE,TextAlignH::Center);
 let samples=frame(d,board,"BOUND COPY • switch Language mode",1900.,130.,LayoutDirection::Horizontal,22.,[20.;4]);fill(d,samples,"0E2A50",1.);for k in ["Who Am I?","Chameleon","Start game","Christmas"]{let t=text(d,samples,&format!("COPY/{k}"),k,430.,58.,28.,700,Color::WHITE,TextAlignH::Center);bind(d,t,&v[k]);}
 Kit{button:b,tile,close,icons}
}

fn category(d:&mut Document,p:NodeId,kit:&Kit,label:&str,var:&str,color:&str)->NodeId{let id=inst(d,p,&format!("Category/{label}"),kit.tile,160.,186.);let n=d.get_mut(id).unwrap();n.component.values.insert("Label".into(),PropValue::Text(label.into()));n.component.values.insert("Icon".into(),PropValue::Instance(kit.icons[label]));n.fills=vec![Paint::solid(c(color).with_alpha(0.52))];n.component.overrides.extend([OverrideField::Name,OverrideField::Fills]);n.variables.bindings.insert("component/Label".into(),var.into());id}
fn button(d:&mut Document,p:NodeId,kit:&Kit,name:&str,label:&str,w:f32)->NodeId{let id=inst(d,p,name,kit.button,w,72.);let n=d.get_mut(id).unwrap();n.component.values.insert("Label".into(),PropValue::Text(label.into()));n.component.overrides.insert(OverrideField::Name);id}
fn phone_screens(d:&mut Document,root:&Path,v:&BTreeMap<String,String>,kit:&Kit)->BTreeMap<String,NodeId>{
 let pg=d.add_page("02 • App Screens • Responsive Phone");let board=frame(d,pg,"PHONE SCREEN MATRIX • Auto Layout",3100.,1000.,LayoutDirection::Horizontal,54.,[70.;4]);fill(d,board,"E8EBEF",1.);let mut out=BTreeMap::new();
 // Categories
 let s=screen(d,board,root,"SCREEN/Home • Categories",390.,844.);mode(d,s,"en");let body=frame(d,s,"CONTENT • Safe area",390.,844.,LayoutDirection::Vertical,14.,[58.,28.,28.,28.]);d.get_mut(body).unwrap().layout_child.vertical=Sizing::Fill;
 let title=text(d,body,"COPY/Screen title","Who Am I?",334.,58.,36.,800,Color::WHITE,TextAlignH::Center);bind(d,title,&v["Who Am I?"]);
 let tabs=frame(d,body,"Segmented control",334.,54.,LayoutDirection::Horizontal,4.,[4.;4]);fill(d,tabs,"FFFFFF",0.17);outline(d,tabs,"FFFFFF",0.32,1.);round(d,tabs,18.);for k in ["Who Am I?","Chameleon"]{let t=text(d,tabs,&format!("COPY/Tab/{k}"),k,161.,42.,18.,700,Color::WHITE,TextAlignH::Center);bind(d,t,&v[k]);}
 let grid=frame(d,body,"CATEGORY GRID • wraps at 2 columns",334.,600.,LayoutDirection::Horizontal,14.,[0.;4]);d.get_mut(grid).unwrap().kind.frame_props_mut().unwrap().auto_layout.as_mut().unwrap().wrap=true;for (k,col) in [("Animals","35A3ED"),("Music","E21D60"),("Movies","F09200"),("Tv Show","6AB04C"),("Food","F1BA08"),("History","34495E")]{category(d,grid,kit,k,&v[k],col);}out.insert("home".into(),s);
 // Landscape gameplay
 let g=screen(d,board,root,"SCREEN/Who Am I • Gameplay landscape",844.,390.);let gc=frame(d,g,"CONTENT • centered",844.,390.,LayoutDirection::Vertical,16.,[28.,60.,28.,60.]);d.get_mut(gc).unwrap().layout_child.vertical=Sizing::Fill;text(d,gc,"Timer","57",100.,60.,34.,800,Color::WHITE,TextAlignH::Center);text(d,gc,"GAME/Word","Shark",724.,115.,76.,800,Color::WHITE,TextAlignH::Center);out.insert("game".into(),g);
 // Setup
 let st=screen(d,board,root,"SCREEN/Chameleon Setup",390.,844.);let sc=frame(d,st,"CONTENT • Safe area",390.,844.,LayoutDirection::Vertical,12.,[54.,20.,30.,20.]);d.get_mut(sc).unwrap().layout_child.vertical=Sizing::Fill;let h=text(d,sc,"COPY/Title","Chameleon setup",350.,54.,34.,800,Color::WHITE,TextAlignH::Center);bind(d,h,&v["Chameleon setup"]);
 let count=card(d,sc,"Chameleon count",350.,74.);let ct=text(d,count,"COPY/Chameleons","Chameleons",314.,30.,23.,700,Color::WHITE,TextAlignH::Left);bind(d,ct,&v["Chameleons"]);let cp=text(d,count,"COPY/Players","Players: 4",314.,24.,17.,500,c("C5E8E2"),TextAlignH::Left);bind(d,cp,&v["Players"]);
 for name in ["Alex","Jamie","Sam","Robin"]{let row=frame(d,sc,&format!("Player row/{name}"),350.,66.,LayoutDirection::Horizontal,10.,[10.,16.,10.,16.]);fill(d,row,"FFFFFF",0.16);outline(d,row,"FFFFFF",0.3,1.);round(d,row,22.);text(d,row,"Player name",name,210.,40.,25.,700,Color::WHITE,TextAlignH::Left);text(d,row,"Remove","−",44.,44.,29.,600,c("FF6464"),TextAlignH::Center);text(d,row,"Drag handle","≡",44.,44.,25.,600,c("C5E8E2"),TextAlignH::Center);}
 let add=card(d,sc,"Add player",350.,62.);text(d,add,"COPY/Add player","＋  Player 5",314.,34.,23.,700,c("C5E8E2"),TextAlignH::Center);button(d,sc,kit,"CTA/Start game","▶  Start game",350.);out.insert("setup".into(),st);
 // Role
 let r=screen(d,board,root,"SCREEN/Secret Role",390.,844.);let rc=frame(d,r,"CONTENT • Safe area",390.,844.,LayoutDirection::Vertical,24.,[70.,36.,34.,36.]);d.get_mut(rc).unwrap().layout_child.vertical=Sizing::Fill;let yt=text(d,rc,"COPY/Your turn","Your turn",318.,36.,22.,600,c("C5E8E2"),TextAlignH::Center);bind(d,yt,&v["Your turn"]);text(d,rc,"Player name","Sam",318.,64.,44.,800,Color::WHITE,TextAlignH::Center);let reveal=card(d,rc,"Reveal card",280.,280.);round(d,reveal,140.);text(d,reveal,"Hidden word","????????",244.,80.,47.,800,Color::WHITE,TextAlignH::Center);let hold=text(d,reveal,"COPY/Hold to reveal","Hold to reveal your word",244.,54.,20.,500,c("C5E8E2"),TextAlignH::Center);bind(d,hold,&v["Hold to reveal your word"]);button(d,rc,kit,"CTA/Next player","Next player",280.);out.insert("role".into(),r);
 // Reveal
 let rv=screen(d,board,root,"SCREEN/Reveal Results",390.,844.);let vc=frame(d,rv,"CONTENT • Safe area",390.,844.,LayoutDirection::Vertical,24.,[88.,20.,40.,20.]);d.get_mut(vc).unwrap().layout_child.vertical=Sizing::Fill;for (label,value,border) in [("The secret word was:","Horse","148A06"),("The Chameleon was:","Sam","E85B61")]{let x=card(d,vc,&format!("Result/{label}"),350.,152.);outline(d,x,border,0.85,1.5);let l=text(d,x,&format!("COPY/{label}"),label,314.,40.,22.,600,c("C5E8E2"),TextAlignH::Center);bind(d,l,&v[label]);text(d,x,"Result value",value,314.,60.,40.,800,Color::WHITE,TextAlignH::Center);}button(d,vc,kit,"CTA/Play again","Play again",280.);button(d,vc,kit,"CTA/Main menu","Main menu",280.);out.insert("reveal".into(),rv);
 let _=kit.close;out
}

fn tablet_screens(d:&mut Document,root:&Path,phone:&BTreeMap<String,NodeId>)->BTreeMap<String,NodeId>{let pg=d.add_page("03 • App Screens • Responsive Tablet");let board=frame(d,pg,"TABLET VARIANTS",3400.,1600.,LayoutDirection::Horizontal,80.,[80.;4]);fill(d,board,"E8EBEF",1.);let mut out=BTreeMap::new();for (key,title) in [("home","Home / categories"),("setup","Chameleon setup"),("reveal","Reveal results")]{let s=screen(d,board,root,&format!("TABLET/{title}"),1024.,1366.);let wrap=frame(d,s,"Responsive content • max-width 760",1024.,1366.,LayoutDirection::Vertical,28.,[90.,132.,80.,132.]);d.get_mut(wrap).unwrap().layout_child.vertical=Sizing::Fill;text(d,wrap,"Variant title",title,760.,80.,48.,800,Color::WHITE,TextAlignH::Center);let i=inst(d,wrap,"Linked app screen component",phone[key],390.,844.);d.get_mut(i).unwrap().layout_child.horizontal=Sizing::Fill;out.insert(key.into(),s);}out}

fn localization(d:&mut Document,phone:&BTreeMap<String,NodeId>){let pg=d.add_page("04 • Localization • EN DA NO SV");let b=frame(d,pg,"LANGUAGE PREVIEWS",1900.,1100.,LayoutDirection::Horizontal,64.,[72.;4]);fill(d,b,"F3F4F6",1.);for (m,label) in [("en","English"),("da","Dansk"),("no","Norsk"),("sv","Svenska")]{let col=frame(d,b,&format!("LOCALE/{label}"),390.,930.,LayoutDirection::Vertical,18.,[20.;4]);fill(d,col,"0E2A50",1.);mode(d,col,m);text(d,col,"Language",label,350.,54.,28.,800,Color::WHITE,TextAlignH::Center);let i=inst(d,col,"Localized screen",phone["home"],350.,758.);d.get_mut(i).unwrap().layout_child.horizontal=Sizing::Fill;}}

fn device(d:&mut Document,p:NodeId,name:&str,w:f32,h:f32,src:NodeId,sw:f32,sh:f32)->NodeId{let wrap=frame(d,p,name,w,h,LayoutDirection::Vertical,0.,[0.;4]);let shell=frame(d,wrap,"DEVICE SHELL • scalable",430.,880.,LayoutDirection::Vertical,0.,[18.;4]);fill(d,shell,"111827",1.);outline(d,shell,"FFFFFF",0.7,4.);round(d,shell,64.);let scale=(w/430.).min(h/880.);let sn=d.get_mut(shell).unwrap();sn.layout_child.absolute=true;sn.transform=Affine{a:scale,b:0.,c:0.,d:scale,tx:(w-430.*scale)/2.,ty:(h-880.*scale)/2.};inst(d,shell,"SCREEN SLOT • linked design",src,sw,sh);wrap}
fn store_art(d:&mut Document,p:NodeId,name:&str,w:f32,h:f32,src:NodeId,season:&str,v:&BTreeMap<String,String>)->NodeId{let x=frame(d,p,name,w,h,LayoutDirection::Vertical,28.,[90.,80.,90.,80.]);fill(d,x,if season=="Christmas"{"0B443A"}else{"35C7BE"},1.);mode(d,x,"en");d.get_mut(x).unwrap().export_settings.push(ExportPreset{format:ExportFileFormat::Png,constraint:ExportConstraint::Scale(1.),suffix:String::new()});let hk=if season=="Christmas"{"CHRISTMAS GAME NIGHT"}else{"BIG LAUGHS. TINY CLUES."};let hnode=text(d,x,"STORE COPY/Headline",hk,w-160.,150.,72.,900,Color::WHITE,TextAlignH::Center);bind(d,hnode,&v[hk]);let sub=text(d,x,"STORE COPY/Subheadline","A fast party game for every group",w-160.,95.,36.,600,c("0E2A50"),TextAlignH::Center);bind(d,sub,&v["A fast party game for every group"]);if season=="Christmas"{let badge=frame(d,x,"CAMPAIGN/Christmas badge",w-300.,82.,LayoutDirection::Horizontal,0.,[12.,24.,12.,24.]);fill(d,badge,"D63C32",1.);round(d,badge,41.);let t=text(d,badge,"Campaign label","CHRISTMAS EDITION",w-348.,50.,28.,900,Color::WHITE,TextAlignH::Center);bind(d,t,&v["CHRISTMAS EDITION"]);}device(d,x,"DEVICE/Responsive phone",w*0.70,h*0.68,src,390.,844.);x}
fn store_pages(d:&mut Document,phone:&BTreeMap<String,NodeId>,tablet:&BTreeMap<String,NodeId>,v:&BTreeMap<String,String>){for (page_name,season) in [("05 • Store Pictures • Default","Default"),("06 • Store Pictures • Christmas","Christmas")]{let pg=d.add_page(page_name);let b=frame(d,pg,"STORE EXPORT MATRIX",6200.,3200.,LayoutDirection::Horizontal,90.,[100.;4]);fill(d,b,"F3F4F6",1.);for (name,w,h) in [("iPhone 6.7",1290.,2796.),("iPhone 6.5",1242.,2688.),("Google Play phone",1080.,1920.)]{store_art(d,b,&format!("EXPORT/{name}/{season}"),w,h,phone["home"],season,v);}let tab=frame(d,b,&format!("EXPORT/iPad/{season}"),2064.,2752.,LayoutDirection::Vertical,36.,[110.;4]);fill(d,tab,if season=="Christmas"{"0B443A"}else{"35C7BE"},1.);mode(d,tab,"en");d.get_mut(tab).unwrap().export_settings.push(ExportPreset{format:ExportFileFormat::Png,constraint:ExportConstraint::Scale(1.),suffix:String::new()});let hk=if season=="Christmas"{"CHRISTMAS GAME NIGHT"}else{"ONE APP. ENDLESS LAUGHS."};let h=text(d,tab,"STORE COPY/Headline",hk,1844.,180.,96.,900,Color::WHITE,TextAlignH::Center);bind(d,h,&v[hk]);device(d,tab,"DEVICE/Responsive tablet",1160.,1500.,tablet["home"],1024.,1366.);}}
fn readme(d:&mut Document){let pg=d.add_page("00 • README");let f=frame(d,pg,"README",1700.,1100.,LayoutDirection::Vertical,28.,[90.;4]);fill(d,f,"0E2A50",1.);text(d,f,"Title","Hint Master • Editable Design System",1520.,100.,58.,900,Color::WHITE,TextAlignH::Left);for (n,s) in [("Purpose","Real editable layers — screenshots are not used as screen content."),("Workflow","Edit components or language variables once; App Screens and Store Pictures reuse them."),("Localization","English, Dansk, Norsk and Svenska. Screen labels and categories are bound to the app's translation source."),("Store Pictures","Default and Christmas pages contain export-ready device canvases. Duplicate a campaign page for future promotions."),("Responsive","Phone and tablet masters use Auto Layout, fill sizing and max-width content containers.")]{text(d,f,n,s,1520.,120.,30.,if n=="Purpose"{700}else{500},if n=="Purpose"{Color::WHITE}else{c("C5E8E2")},TextAlignH::Left);}}
fn find_named(d:&Document,id:NodeId,name:&str)->Option<NodeId>{for child in &d.get(id)?.children{if d.get(*child)?.name==name{return Some(*child)}if let Some(found)=find_named(d,*child,name){return Some(found)}}None}
fn bind_instance_copy(d:&mut Document,v:&BTreeMap<String,String>){let ids:Vec<NodeId>=d.nodes.keys().copied().collect();for id in ids{let name=d.get(id).unwrap().name.clone();let key=if let Some(k)=name.strip_prefix("Category/"){Some(k.to_string())}else if let Some(k)=name.strip_prefix("CTA/"){Some(k.to_string())}else{None};if let Some(key)=key{if let (Some(var),Some(label))=(v.get(&key),find_named(d,id,"Label")){bind(d,label,var);let n=d.get_mut(label).unwrap();n.component.bindings.remove(&OverrideField::Characters);n.component.overrides.insert(OverrideField::Characters);}}}}
fn main(){let a:Vec<String>=std::env::args().collect();let root=PathBuf::from(&a[1]);let out=PathBuf::from(&a[2]);let mut d=Document::new("Hint Master • Editable Responsive Design System");readme(&mut d);let v=variables(&mut d,&root);let k=kit(&mut d,&root,&v);let phone=phone_screens(&mut d,&root,&v,&k);let tablet=tablet_screens(&mut d,&root,&phone);localization(&mut d,&phone);store_pages(&mut d,&phone,&tablet,&v);let mut components:Vec<NodeId>=k.icons.values().copied().collect();components.extend([k.button,k.tile,k.close]);components.extend(phone.values().copied());components.extend(tablet.values().copied());for id in components{let _=sync_instances(&mut d,id).apply(&mut d);}bind_instance_copy(&mut d,&v);let roots:Vec<NodeId>=d.pages.iter().filter_map(|p|d.get(*p)).flat_map(|p|p.children.clone()).collect();let mut edit=Edit::new();for r in roots{layout_node(&mut d,&mut edit,r);}if let Some(p)=out.parent(){fs::create_dir_all(p).unwrap();}fs::write(&out,d.to_json().unwrap()).unwrap();println!("{}",out.display());}
